import json, sys
from pathlib import Path
root = Path('/home/elliot/playground/Wirestack-pr-worktrees/M8-004-publication')
sys.path.insert(0, str(root))
from tools.evidence_digest import text_evidence_digest, artifact_byte_digest
checked = []
issues = []
def visit(value, report):
    if isinstance(value, dict):
        if isinstance(value.get('path'), str) and isinstance(value.get('digest'), dict):
            path = root / value['path']
            try:
                digest = text_evidence_digest(path) if value['digest']['domain'] == 'text-utf8-lf-v1' else artifact_byte_digest(path)
                if digest.sha256 != value['digest']['sha256']:
                    issues.append({'report':str(report.relative_to(root)), 'path':value['path'], 'error':'digest mismatch'})
                checked.append(value['path'])
            except Exception as error:
                issues.append({'report':str(report.relative_to(root)), 'path':value['path'], 'error':str(error)})
        for item in value.values():
            visit(item,report)
    elif isinstance(value,list):
        for item in value:
            visit(item,report)
reports = list((root/'docs/evidence/M8-004').glob('native*.json'))
reports.append(root/'docs/evidence/M8-004/development/acceptance-first/native-dns.json')
reports.extend(root / name for name in ['docs/evidence/M8-004/pr160-system-fallback-red.json', 'docs/evidence/M8-004/pr160-system-fallback-red-confirmed.json', 'docs/evidence/M8-004/pr160-system-fallback-green.json', 'docs/evidence/M8-004/pr160-system-fallback-green-confirmed.json'])
for report in reports:
    visit(json.loads(report.read_text()),report)
print(json.dumps({'status':'PASS' if not issues else 'FAIL','reports':len(reports),'raw_log_references':len(checked),'issues':issues},indent=2))
sys.exit(bool(issues))
